#!/usr/bin/env node
// Big legacy docker-save fixture assertion (desktop viewport): uploads the
// ~3 GB fixture generated by tools/ci/build-big-legacy.mjs through the real
// file input in REAL Chromium and asserts:
//   - the analysis finishes (or an error box is dumped with the exact text)
//   - zero console/page errors
//   - layers / total size / wasted bytes / reclaimable / efficiency equal the
//     values computed independently by tools/ci/analyze-big.mjs on the same file
//     (compared as the exact strings the UI renders)
//   - elapsed time and sampled peak JS heap (usedJSHeapSize) are recorded
//     (RSS is not exposed to the page; the node-side peak RSS is reported by
//     the reference step instead)
//
//   node tools/browser-big.mjs --url http://127.0.0.1:8321 --image /tmp/bench/big-legacy.tar --expected /tmp/bench/big-expected.json

import { chromium } from 'playwright-core';
import { existsSync, readFileSync, writeFileSync } from 'node:fs';

const args = process.argv.slice(2);
const getArg = (flag) => { const i = args.indexOf(flag); return i >= 0 ? args[i + 1] : null; };
const url = getArg('--url') || 'http://127.0.0.1:8321';
const image = getArg('--image');
const expectedPath = getArg('--expected');
const metricsOut = getArg('--metrics-out'); // optional: write browser metrics JSON here
if (!image || !expectedPath) { console.error('usage: node tools/browser-big.mjs --url URL --image TAR --expected JSON [--metrics-out FILE]'); process.exit(2); }
if (!existsSync(image)) { console.error(`fixture not found: ${image}`); process.exit(2); }
if (!existsSync(expectedPath)) { console.error(`expected json not found: ${expectedPath}`); process.exit(2); }
const expected = JSON.parse(readFileSync(expectedPath, 'utf8'));

const DESKTOP = { width: 1440, height: 900 };
const ANALYSIS_TIMEOUT_MS = 12 * 60 * 1000;

const browser = await chromium.launch();
let failures = 0;
const fail = (msg) => { failures++; console.error(`::error::browser-big: ${msg}`); };

const page = await browser.newPage({ viewport: DESKTOP });
const consoleErrors = [];
page.on('pageerror', (e) => consoleErrors.push(`pageerror: ${e.message}`));
page.on('console', (m) => { if (m.type() === 'error') consoleErrors.push(`console: ${m.text()}`); });

await page.goto(url, { waitUntil: 'load', timeout: 60000 });

// in-page heap sampler (usedJSHeapSize via performance.memory, Chromium-only)
await page.evaluate(() => {
  window.__heapPeak = 0;
  window.__heapStart = performance.memory ? performance.memory.usedJSHeapSize : null;
  window.__heapLimit = performance.memory ? performance.memory.jsHeapSizeLimit : null;
  window.__heapSamples = 0;
  window.__heapSampler = setInterval(() => {
    const mem = performance.memory;
    if (!mem) return;
    window.__heapSamples += 1;
    if (mem.usedJSHeapSize > window.__heapPeak) window.__heapPeak = mem.usedJSHeapSize;
  }, 200);
});

const t0 = Date.now();
await page.setInputFiles('#file-input', image);

const outcome = await Promise.race([
  page.waitForFunction(() => {
    const a = document.getElementById('analysis');
    const o = document.getElementById('progress-overlay');
    return a && !a.hidden && o && o.hidden;
  }, null, { timeout: ANALYSIS_TIMEOUT_MS, polling: 250 }).then(() => 'ok'),
  page.waitForSelector('#error-box', { state: 'visible', timeout: ANALYSIS_TIMEOUT_MS }).then(() => 'error'),
]).catch(() => 'timeout');
const elapsedMs = Date.now() - t0;

if (outcome === 'error') {
  const text = await page.$eval('#error-box', (el) => el.textContent.trim());
  fail(`analysis failed in the browser for ${image}: ${text}`);
} else if (outcome === 'timeout') {
  fail(`analysis did not finish within ${ANALYSIS_TIMEOUT_MS / 60000} minutes (desktop 1440x900) — the engine was not changed; see report`);
} else {
  await page.evaluate(() => clearInterval(window.__heapSampler));
  const heap = await page.evaluate(() => ({
    peak: window.__heapPeak,
    start: window.__heapStart,
    limit: window.__heapLimit,
    samples: window.__heapSamples,
    after: performance.memory ? performance.memory.usedJSHeapSize : null,
  }));
  const got = await page.evaluate(() => ({
    chipLayers: document.getElementById('chip-layers')?.textContent ?? null,
    statTotal: document.getElementById('stat-total')?.textContent ?? null,
    statWasted: document.getElementById('stat-wasted')?.textContent ?? null,
    statReclaimable: document.getElementById('stat-reclaimable')?.textContent ?? null,
    gaugeValue: document.getElementById('gauge-value')?.textContent ?? null,
    wsEfficiency: document.getElementById('ws-efficiency')?.textContent ?? null,
    wsWasted: document.getElementById('ws-wasted')?.textContent ?? null,
    wsReclaimable: document.getElementById('ws-reclaimable')?.textContent ?? null,
    wsPaths: document.getElementById('ws-paths')?.textContent ?? null,
  }));
  console.log(`::notice::browser-big metrics: elapsedMs=${elapsedMs} heapPeakBytes=${heap.peak} heapStartBytes=${heap.start} heapAfterBytes=${heap.after} heapLimitBytes=${heap.limit} heapSamples=${heap.samples}`);
  console.log(`::notice::browser-big numbers (ui): ${JSON.stringify(got)}`);
  console.log(`::notice::browser-big numbers (node reference): ${JSON.stringify(expected.display)} nodeElapsedMs=${expected.elapsedMs} nodeRssPeakBytes=${expected.rssPeakBytes} nodeHeapUsedPeakBytes=${expected.heapUsedPeakBytes}`);
  if (metricsOut) {
    writeFileSync(metricsOut, JSON.stringify({
      image,
      elapsedMs,
      heap: { peak: heap.peak, start: heap.start, after: heap.after, limit: heap.limit, samples: heap.samples },
      nodeReference: { elapsedMs: expected.elapsedMs, rssPeakBytes: expected.rssPeakBytes, heapUsedPeakBytes: expected.heapUsedPeakBytes },
      display: got,
    }, null, 2));
  }

  const want = expected.display;
  for (const key of Object.keys(want)) {
    if (got[key] !== want[key]) fail(`${key}: browser reports ${JSON.stringify(got[key])}, node reference reports ${JSON.stringify(want[key])}`);
  }
  if (consoleErrors.length) fail(`console/page errors: ${consoleErrors.join(' | ')}`);
}

await browser.close();
if (failures > 0) {
  console.error(`browser-big FAILED with ${failures} failure(s) (engine unchanged)`);
  process.exit(1);
}
console.log(`::notice::browser-big PASS — layers=${expected.layers} total=${expected.totalBytes} wasted=${expected.wastedBytes} elapsedMs=${elapsedMs}`);
